WHERE d.EMP_ID = #{empId}

  AND d.APRVL_DOC_STTS_CD = #{documentStatus}


  AND (
      d.DOC_TTL LIKE '%' || #{keyword} || '%'
      OR EXISTS (
          SELECT 1
          FROM TB_APRVL_LINE lk
          JOIN TB_EMPLOYEE ek ON ek.EMP_ID = lk.APRVR_EMP_ID
          WHERE lk.DRFT_DOC_SN = d.DRFT_DOC_SN
            AND ek.EMP_NM LIKE '%' || #{keyword} || '%'
      )
  )

WHERE EXISTS (
    SELECT 1
    FROM TB_APRVL_LINE mine
    WHERE mine.DRFT_DOC_SN = d.DRFT_DOC_SN
      AND mine.APRVR_EMP_ID = #{empId}
      AND mine.APRVL_PRGRS_CD IN ('02', '03')
)

